UPDATE twelve_runner_task
SET assignee_id = #{runnerId},
    status = 'accepted',
    assign_time = #{now},
    update_time = NOW()
WHERE id = #{taskId}
  AND status = 'pending'
  AND deadline > #{now}
  AND publisher_id != #{runnerId}
AND tenant_id = #{tenantId}

UPDATE twelve_runner_task
SET status = #{toStatus}, update_time = NOW()
WHERE id = #{taskId} AND status = #{fromStatus}
AND tenant_id = #{tenantId}

UPDATE twelve_runner_task
SET status = #{toStatus}, ${timeColumn} = NOW(), update_time = NOW()
WHERE id = #{taskId} AND status = #{fromStatus}
AND tenant_id = #{tenantId}

UPDATE twelve_runner_task
SET status = #{status}, cancel_reason = #{cancelReason}, update_time = NOW()
WHERE id = #{taskId}
AND tenant_id = #{tenantId}

mapper.select:
SELECT 
FROM twelve_runner_task
WHERE status = 'pending' AND deadline > NOW()
  AND (is_paid = 0 OR pay_status = 'paid')
AND tenant_id = #{tenantId}
AND task_type = #{taskType}
AND price >= #{minPrice}
AND price <= #{maxPrice}
ORDER BY price DESC, create_time DESC
LIMIT #{limit}

SELECT 
FROM twelve_runner_task
WHERE publisher_id = #{publisherId}
AND tenant_id = #{tenantId}
AND status = #{status}
ORDER BY create_time DESC
LIMIT #{limit}

SELECT 
FROM twelve_runner_task
WHERE assignee_id = #{runnerId}
AND tenant_id = #{tenantId}
AND status = #{status}
ORDER BY assign_time DESC
LIMIT #{limit}

SELECT 
FROM twelve_runner_task
WHERE id = #{taskId}
AND tenant_id = #{tenantId}

SELECT 
FROM twelve_runner_task
WHERE status = 'pending' AND deadline <= #{now}

LIMIT #{limit}

SELECT 
FROM twelve_runner_task
WHERE status = 'pending_confirm' AND finish_time <= #{now}

LIMIT #{limit}

