UPDATE twelve_runner_task
SET pay_order_id = #{payOrderId}, update_time = NOW()
WHERE id = #{taskId}

UPDATE twelve_runner_task
SET finish_images = #{finishImages}, update_time = NOW()
WHERE id = #{taskId}

UPDATE twelve_runner_task
SET pay_order_id = #{payOrderId}, pay_out_trade_no = #{payOutTradeNo}, update_time = NOW()
WHERE id = #{taskId}

UPDATE twelve_runner_task
SET pay_status = #{payStatus}, update_time = NOW()
WHERE pay_out_trade_no = #{payOutTradeNo}
